      first start;
      then if ((io_5_valid) and (((io_5) == (6)))) {
        first start;
        then assign lightOn := true;
      }
      then if ((io_5_valid) and (((io_5) == (5)))) {
        first start;
        then assign lightOn := false;
      }
      then if ((io_5_valid) and (((io_5) == (3)))) {
        first start;
        then assign count := 0;
      }
      then if ((io_0) and ((not prevIo0))) {
        first start;
        then assign lightOn := true;
        then assign count := count + 1;
      }
      then if ((io_1) and ((not prevIo1))) {
        first start;
        then assign lightOn := false;
        then assign count := count + 1;
      }
      then assign prevIo0 := io_0;
      then assign prevIo1 := io_1;
    }
